   2: // Same handler contract as lib/groups.mjs: it returns a new store instead of changing the one it gets.
   3: import { NOT_FOUND, findGroup } from './groups.mjs'
   4: import { balances, expenseView, paymentView } from './ledger.mjs'
   5: import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
   6: 
   7: const BODY_FIELDS = ['entries', 'dry_run', 'skip_recorded']
   8: const MAX_ENTRIES = 50
   9: const ENTRY_FIELDS = {
  10:   expense: ['type', 'description', 'payer', 'amount', 'split'],
  11:   payment: ['type', 'from', 'to', 'amount'],
  12: }
  13: 
  14: // A rule broken by one entry; caught per entry and listed in the 422 reply.
  15: class EntryProblem extends Error {
  16:   constructor(rule) {
  17:     super(rule)
  18:     this.rule = rule
  19:   }
  20: }
  21: 
  22: // Runs parse, turning its ValidationError into the entry rule `rule`.
  23: function check(rule, parse) {
  24:   try {
  25:     return parse()
  26:   } catch (err) {
  27:     if (err instanceof ValidationError) throw new EntryProblem(rule)
  28:     throw err
  29:   }
  30: }
  31: 
  32: // Checks the body fields in the order the README lists them; throws ValidationError (400) on the first bad one.
  33: function parseImportBody(body) {
  34:   const unknown = Object.keys(body).find(key => !BODY_FIELDS.includes(key))
  35:   if (unknown !== undefined) throw new ValidationError(`unknown field ${unknown}`)
  36:   const { entries } = body
  37:   if (!Array.isArray(entries) || entries.length < 1 || entries.length > MAX_ENTRIES) {
  38:     throw new ValidationError(`entries must be an array of 1 to ${MAX_ENTRIES} items`)
  39:   }
  40:   const flag = name => {
  41:     if (!Object.hasOwn(body, name)) return false
  42:     if (typeof body[name] !== 'boolean') throw new ValidationError(`${name} must be true or false`)
  43:     return body[name]
  44:   }
  45:   return { entries, dryRun: flag('dry_run'), skipRecorded: flag('skip_recorded') }
  46: }
  47: 
  48: // One entry as { type, fields }, the fields as the POST routes would store them; throws EntryProblem.
  49: function parseEntry(entry, group) {
  50:   if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) throw new EntryProblem('not-an-object')
  51:   const { type } = entry
  52:   if (type !== 'expense' && type !== 'payment') throw new EntryProblem('bad-type')
  53:   if (Object.keys(entry).some(key => !ENTRY_FIELDS[type].includes(key))) throw new EntryProblem('unknown-field')
  54:   const { members } = group
  55:   if (type === 'expense') {
  56:     // The same parsers, in the same order, as POST /groups/:id/expenses; a missing split means every member.
  57:     const fields = {
  58:       description: check('bad-description', () => parseDescription(entry.description)),
  59:       payer: check('bad-payer', () => parseMember(entry.payer, members, 'bad payer')),
  60:       amount: check('bad-amount', () => parseAmount(entry.amount)),
  61:       split: check('bad-split', () => parseSplit(entry.split, members)),
  62:     }
  63:     return { type, fields }
  64:   }
  65:   const from = check('bad-from', () => parseMember(entry.from, members, 'bad from'))
  66:   const to = check('bad-to', () => parseMember(entry.to, members, 'bad to'))
  67:   if (to === from) throw new EntryProblem('bad-to')
  68:   return { type, fields: { from, to, amount: check('bad-amount', () => parseAmount(entry.amount)) } }
  69: }
