  71: // Expenses match when payer, amount in cents and description (trimmed, lower case) are the same.
  72: const expenseKey = ({ payer, amount, description }) => JSON.stringify([payer, amount, description.trim().toLowerCase()])
  73: 
  74: export function importEntries({ state, params, body }) {
  75:   const group = findGroup(state, params[0])
  76:   if (!group) return NOT_FOUND
  77:   const { entries, dryRun, skipRecorded } = parseImportBody(body)
  78: 
  79:   const recorded = new Set(state.expenses.filter(e => e.group === group.id).map(expenseKey))
  80:   const seen = new Set()
  81:   const problems = []
  82:   const accepted = []
  83:   const skipped = []
  84:   entries.forEach((entry, index) => {
  85:     let parsed
  86:     try {
  87:       parsed = parseEntry(entry, group)
  88:     } catch (err) {
  89:       if (!(err instanceof EntryProblem)) throw err
  90:       problems.push({ index, rule: err.rule })
  91:       return
  92:     }
  93:     if (parsed.type === 'expense') {
  94:       const key = expenseKey(parsed.fields)
  95:       const isDuplicate = seen.has(key)
  96:       seen.add(key)
  97:       if (isDuplicate) {
  98:         problems.push({ index, rule: 'duplicate' })
  99:         return
 100:       }
 101:       if (recorded.has(key)) {
 102:         if (skipRecorded) skipped.push(index)
 103:         else problems.push({ index, rule: 'already-recorded' })
 104:         return
 105:       }
 106:     }
 107:     accepted.push(parsed)
 108:   })
 109:   if (problems.length > 0) return { status: 422, body: { error: 'import rejected', problems } }
 110: 
 111:   let { nextExpenseId, nextPaymentId } = state
 112:   const expenses = []
 113:   const payments = []
 114:   for (const { type, fields } of accepted) {
 115:     if (type === 'expense') expenses.push({ id: nextExpenseId++, group: group.id, ...fields })
 116:     else payments.push({ id: nextPaymentId++, group: group.id, ...fields })
 117:   }
 118:   const next = {
 119:     ...state,
 120:     expenses: [...state.expenses, ...expenses],
 121:     payments: [...state.payments, ...payments],
 122:     nextExpenseId,
 123:     nextPaymentId,
 124:   }
 125:   const reply = {
 126:     status: dryRun ? 200 : 201,
 127:     body: {
 128:       expenses: expenses.map(expenseView),
 129:       payments: payments.map(paymentView),
 130:       skipped,
 131:       balances: balances(next, group),
 132:     },
 133:   }
 134:   // Nothing to write on a dry run, or when every entry was skipped.
 135:   return dryRun || accepted.length === 0 ? reply : { ...reply, state: next }
 136: }
